<?php
/** Proof — vendors and contacts (spec "Proof", 1): as slice 4's customers; an ai_provider vendor read-only on kind; an employee vendor linked to a member. */
require __DIR__ . '/lib.php';
$bea = as_member(27); $carl = as_member(28); $vera = as_member(26);
$fx = ap_fixture();
echo "1. Add and change\n";
$since = last_activity_id();
[$c, $b] = act($bea, '/vendors/save.php', ['name' => 'SMOKE Hosting Vendor', 'email' => 'Billing@Hosting.Invalid', 'terms_days' => '45', 'currency' => 'usd', 'expense_account' => account_id('6200'), 'pay_method' => 'ach', 'remit_address' => "1 Server Way\nCloud City", 'tax_id' => 'EIN-9', 'notes' => 'Pays on the 5th']);
$V = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $V > 0 && ($b['location'] ?? '') === '/vendors/' . $V . '?notice=saved', "vendor_save: 200, record_id $V, location the vendor");
$row = q('SELECT * FROM vendors WHERE id = :v', ['v' => $V])[0];
ok($row['name'] === 'SMOKE Hosting Vendor' && $row['email'] === 'billing@hosting.invalid' && $row['terms_days'] === 45 + 0 * 1 && $row['currency'] === 'USD' && $row['kind'] === 'vendor' && $row['pay_method'] === 'ach' && (int) $row['expense_account_id'] === account_id('6200'), 'saved: email lower-cased, USD, kind vendor, ach, expense account 6200');
$l = activity('vendor.save', $since)[0]; $a = json_decode((string) $l['after'], true);
ok((int) $l['vendor_id'] === $V && $a['email'] === '(set)' && $a['remit_address'] === '(set)' && $a['tax_id'] === '(set)' && $a['notes'] === '(set)' && !str_contains((string) $l['after'], 'EIN-9') && !str_contains((string) $l['after'], 'billing@'), 'vendor.save logs vendor_id and the contact fields as "(set)" only — never the address, tax id or notes');
[$c, $b] = act($bea, '/vendors/save.php', ['name' => 'smoke hosting vendor']);
ok($c === 422 && str_contains(msg($b), 'A vendor named smoke hosting vendor exists'), 'a duplicate name (case-blind): 422');
[$c, $b] = act($bea, '/vendors/save.php', ['name' => '']);
ok($c === 422 && isset(fields($b)['name']), 'no name: 422 naming the field');
[$c, $b] = act($bea, '/vendors/save.php', ['name' => 'SMOKE Bad', 'terms_days' => '999', 'pay_method' => 'bitcoin', 'currency' => 'dollars', 'kind' => 'ai_provider', 'expense_account' => account_id('4100')]);
$f = fields($b);
ok($c === 422 && isset($f['terms_days'], $f['pay_method'], $f['currency'], $f['kind'], $f['expense_account']), 'bad terms, pay method, currency, kind (ai_provider is not made here) and an income account: 422 with every field named');
$since = last_activity_id();
[$c, $b] = act($bea, '/vendors/save.php', ['vendor' => $V, 'phone' => '555-0100']);
$r2 = q('SELECT * FROM vendors WHERE id = :v', ['v' => $V])[0];
ok($c === 200 && $r2['phone'] === '555-0100' && $r2['terms_days'] === $row['terms_days'] && $r2['email'] === $row['email'] && $r2['remit_address'] === $row['remit_address'], 'a field left out stays as it was');
$l = activity('vendor.save', $since)[0]; $bf = json_decode((string) $l['before'], true); $af = json_decode((string) $l['after'], true);
ok(array_keys($af) === ['phone'] && $bf['phone'] === null && $af['phone'] === '(set)', 'the update logs before/after of the changed field only');
echo "2. The kinds\n";
$ai = (int) one("INSERT INTO vendors (name, kind, provider_key, created_by) VALUES ('SMOKE Anthropic', 'ai_provider', 'smoke-anthropic', 1) RETURNING id");
[$c, $b] = act($bea, '/vendors/save.php', ['vendor' => $ai, 'kind' => 'vendor', 'terms_days' => '10']);
ok($c === 422 && str_contains(msg($b), 'AI provider') || ($c === 422 && isset(fields($b)['kind'])), 'an AI provider\'s kind does not change (' . msg($b) . ')');
[$c, $b] = act($bea, '/vendors/save.php', ['vendor' => $ai, 'terms_days' => '10']);
ok($c === 200 && (string) one('SELECT kind FROM vendors WHERE id = :v', ['v' => $ai]) === 'ai_provider' && (int) one('SELECT terms_days FROM vendors WHERE id = :v', ['v' => $ai]) === 10, 'but its terms may: it stays an ai_provider');
$body = page($bea, '/vendors/')['body'];
ok(str_contains($body, 'id="vendor-card-' . $ai . '-kind"') && str_contains($body, 'AI provider') && str_contains($body, 'feather-cpu'), 'the list marks the AI provider (chip with feather-cpu)');
$body = page($bea, '/vendors/' . $ai . '/edit')['body'];
ok(str_contains($body, 'id="vendor-form-field-kind"') && preg_match('/id="vendor-form-field-kind"[^>]*disabled/', $body) === 1, 'its kind select is disabled on the form');
[$c, $b] = act($owner = as_member(1), '/vendors/save.php', ['name' => 'SMOKE Staff Reimbursements', 'kind' => 'employee', 'member' => 27, 'pay_method' => 'ach']);
$emp = (int) ($b['record_id'] ?? 0);
ok($c === 200 && (string) one('SELECT kind FROM vendors WHERE id = :v', ['v' => $emp]) === 'employee' && (int) one('SELECT member_id FROM vendors WHERE id = :v', ['v' => $emp]) === 27, 'an employee vendor linked to the member');
[$c, $b] = act($bea, '/vendors/save.php', ['name' => 'SMOKE Tax Office', 'kind' => 'tax_authority']);
ok($c === 200 && (string) one("SELECT kind FROM vendors WHERE name = 'SMOKE Tax Office'") === 'tax_authority', 'a tax authority');
[$c, $b] = act($bea, '/vendors/save.php', ['name' => 'SMOKE Ghost Member', 'member' => 424242]);
ok($c === 422 && isset(fields($b)['member']), 'a member that is not there: 422');
echo "3. Contacts (slice 4's handlers, party_kind vendor)\n";
$since = last_activity_id();
[$c, $b] = act($bea, '/customers/contact.php', ['party_kind' => 'vendor', 'party' => $V, 'name' => 'SMOKE Pat Payable', 'email' => 'pat@hosting.invalid', 'role' => 'Accounts', 'is_primary' => 'yes']);
$k1 = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $k1 > 0 && ($b['location'] ?? '') === '/vendors/' . $V . '?notice=saved#contact-' . $k1, 'contact_save for a vendor: 200 and back to the vendor');
[$c, $b] = act($bea, '/customers/contact.php', ['party_kind' => 'vendor', 'party' => $V, 'name' => 'SMOKE Sam Second', 'is_primary' => 'yes']);
$k2 = (int) $b['record_id'];
ok((int) one("SELECT count(*) FROM party_contacts WHERE party_kind = 'vendor' AND party_id = :v AND is_primary", ['v' => $V]) === 1 && (bool) one('SELECT is_primary FROM party_contacts WHERE id = :k', ['k' => $k2]) === true, 'one primary: making the second primary un-primaries the first');
[$c, $b] = act($vera, '/customers/contact.php', ['party_kind' => 'vendor', 'party' => $V, 'name' => 'SMOKE Nope']);
ok($c === 403, 'a Viewer may not add a vendor contact: 403');
$p = page($bea, '/vendors/' . $V)['body'];
ok(str_contains($p, 'id="vendor-contacts"') && str_contains($p, 'SMOKE Pat Payable') && str_contains($p, 'id="vendor-contact-form"'), 'the vendor page renders the contacts partial with its add form');
[$c, $b] = act($bea, '/customers/contact-remove.php', ['contact' => $k1]);
ok($c === 200 && one('SELECT 1 FROM party_contacts WHERE id = :k', ['k' => $k1]) === false, 'contact_remove for a vendor');
echo "4. Reading\n";
$p = page($bea, '/vendors/' . $V)['body'];
ok(str_contains($p, 'billing@hosting.invalid') && str_contains($p, '1 Server Way') && str_contains($p, 'Pays on the 5th') && str_contains($p, 'id="vendor-view-bill-btn"') && str_contains($p, 'id="vendor-view-delete-btn"') === false, 'the Bookkeeper sees the address, notes and the New bill button; no Delete (that is journal.override)');
$p = page($vera, '/vendors/' . $V)['body'];
ok(!str_contains($p, 'billing@hosting.invalid') && !str_contains($p, '1 Server Way') && !str_contains($p, 'Pays on the 5th') && !str_contains($p, 'id="vendor-contacts"') && !str_contains($p, 'id="vendor-view-edit-btn"'), 'the Viewer sees no email, address, notes, contacts or Edit (the view hides them)');
$r = req('GET', '/vendors/', ['headers' => array_merge(JSONH, ['X-Action-Token: ' . person_token(26)])]); $d = json_decode($r['body'], true)['data'] ?? [];
ok($r['code'] === 200 && count($d['vendors'] ?? []) >= 3 && array_key_exists('email', $d['vendors'][0]) && $d['vendors'][0]['email'] === null, 'JSON: the list answers whitelisted vendors; the Viewer\'s emails are null');
$r = req('GET', '/vendors/?q=anthropic', ['jar' => $bea]); 
ok(str_contains($r['body'], 'SMOKE Anthropic') && !str_contains($r['body'], 'SMOKE Hosting Vendor'), 'q filters by name');
$r = req('GET', '/vendors/?kind=ai_provider', ['jar' => $bea]);
ok(str_contains($r['body'], 'SMOKE Anthropic') && !str_contains($r['body'], 'SMOKE Staff Reimbursements'), 'kind filters');
$r = req('GET', '/vendors/', ['jar' => $bea, 'headers' => ['HX-Request: true', 'HX-Target: vendors-results']]);
ok(str_starts_with(trim($r['body']), '<div class="row g-3" id="vendors-results"'), 'the filter swaps only #vendors-results');
echo "5. Open bills, archive, currency, delete\n";
$B = ready_bill($V, [['Server rental', '1', '100.00']], ['vendor_ref' => 'V-1']);
$p = page($bea, '/vendors/' . $V)['body'];
ok(str_contains($p, 'id="vendor-open-' . $B . '"') && str_contains($p, 'no document'), 'the vendor page lists the open bill (with its no-document chip)');
$balances = q('SELECT balance_due, open_bills FROM mcp_vendors WHERE vendor_id = :v', ['v' => $V]);
pdo()->exec("SELECT set_config('app.member_id', '1', false)");
ok((string) one('SELECT balance_due FROM mcp_vendors WHERE vendor_id = :v', ['v' => $V]) === '100.00' && (int) one('SELECT open_bills FROM mcp_vendors WHERE vendor_id = :v', ['v' => $V]) === 1, 'the card figures: 100.00 owed, one open bill');
[$c, $b] = act($bea, '/vendors/archive.php', ['vendor' => $V]);
ok($c === 422 && str_contains(msg($b), 'Pay or void its 1 open bill first'), 'archive refused with an open bill, in words');
[$c, $b] = act($bea, '/vendors/save.php', ['vendor' => $V, 'currency' => 'EUR']);
ok($c === 422 && str_contains(msg($b), 'The currency is fixed once SMOKE Hosting Vendor has a document'), 'the currency is fixed once a document exists');
[$c, $b] = act($carl, '/bills/void.php', ['bill' => $B, 'reason' => 'SMOKE test']);
[$c, $b] = act($bea, '/vendors/archive.php', ['vendor' => $V]);
ok($c === 200 && (string) one('SELECT archived_at IS NOT NULL FROM vendors WHERE id = :v', ['v' => $V]) === '1' && count(activity('vendor.archive', $since)) >= 1, 'archived once the bill is void; vendor.archive logged');
[$c, $b] = act($bea, '/bills/save.php', ['vendor' => $V, 'lines' => '[]']);
ok($c === 422 && isset(fields($b)['vendor']), 'an archived vendor takes no new bill');
[$c, $b] = act($bea, '/vendors/archive.php', ['vendor' => $V, 'archived' => 'no']);
ok($c === 200 && (string) one('SELECT archived_at IS NULL FROM vendors WHERE id = :v', ['v' => $V]) === '1', 'restored');
[$c, $b] = act($bea, '/vendors/delete.php', ['vendor' => $V]);
ok($c === 403, 'a Bookkeeper may not delete (journal.override)');
[$c, $b] = act($carl, '/vendors/delete.php', ['vendor' => $V]);
ok($c === 422 && str_contains(msg($b), 'has bills; archive it instead'), 'delete refused in words when a bill exists');
$since = last_activity_id();
$tmp = mk_vendor('SMOKE Throwaway');
act($bea, '/customers/contact.php', ['party_kind' => 'vendor', 'party' => $tmp, 'name' => 'SMOKE Gone']);
[$c, $b] = act($carl, '/vendors/delete.php', ['vendor' => $tmp]);
ok($c === 200 && one('SELECT 1 FROM vendors WHERE id = :v', ['v' => $tmp]) === false && (int) one("SELECT count(*) FROM party_contacts WHERE party_kind = 'vendor' AND party_id = :v", ['v' => $tmp]) === 0 && count(activity('vendor.delete', $since)) === 1, 'a vendor with no document is deleted with its contacts; vendor.delete logged');
echo "6. The forms\n";
$p = page($bea, '/vendors/new')['body'];
ok(str_contains($p, 'id="vendor-form"') && str_contains($p, 'id="vendor-form-field-name"') && str_contains($p, 'id="vendor-form-field-expense"') && str_contains($p, 'id="vendor-form-field-pay"') && !str_contains($p, 'value="ai_provider"'), 'the add form: name, expense account, pay method; no AI provider kind');
[$c, $b] = act($vera, '/vendors/save.php', ['name' => 'SMOKE Viewer Vendor']);
ok($c === 403 && msg($b) === 'You may not keep the payables.', 'a Viewer saving: 403 in the right\'s sentence');
ok(req('GET', '/vendors/new', ['jar' => $vera])['code'] === 403, 'a Viewer opening the add form: 403');
finish();
